// Brings up a real headless GPU device with the minimum dependency set Graphics requires, mirroring Core::Frame's
// construction. createHeadlessDevice() creates no window/swap chain, so this runs on any host with a Vulkan driver
// that exposes the required descriptor-buffer capability.
class HeadlessGraphicsScope final : NoCopy{
public:
    HeadlessGraphicsScope()
        : m_objectArena(s_TestArenaName)
        , m_allocator(m_objectArena)
        , m_threadPool(s_TestWorkerThreadCount, CpuAffinity::Any)
        , m_jobSystem(m_threadPool)
        , m_gpuTiming(m_objectArena)
        , m_graphics(m_allocator, m_threadPool, m_jobSystem, m_gpuTiming)
    {}

    ~HeadlessGraphicsScope(){}

    // Returns false on driver/instance failure (no Vulkan, no physical device, etc.). The caller SKIPS in that case
    // rather than failing — a CI runner without a GPU is an environment condition.
    [[nodiscard]] bool initialize(){
        if(!m_graphics.setBindlessHeapAbi(Impl::AssetsGraphicsBindless::MakeGpuDescriptorHeapAbi()))
            return false;
        return m_graphics.createHeadlessDevice();
    }

    [[nodiscard]] bool setAsyncComputeLaneEnabled(const bool enabled){
        return m_graphics.setAsyncComputeLaneEnabled(enabled);
    }

    [[nodiscard]] bool setTransferQueueEnabled(const bool enabled){
        return m_graphics.setTransferQueueEnabled(enabled);
    }

    [[nodiscard]] bool setSameClassMultiQueueEnabled(const bool enabled){
        return m_graphics.setSameClassMultiQueueEnabled(enabled);
    }

    [[nodiscard]] Graphics& graphics(){ return m_graphics; }
    [[nodiscard]] Alloc::GlobalArena& arena(){ return m_objectArena; }
    [[nodiscard]] Perf::TimingRecorder& gpuTimingSink(){ return m_gpuTiming; }

    void setGpuTimingEnabled(const bool enabled){
        m_gpuTiming.setEnabled(enabled);
        m_graphics.gpuTiming().setQueryCollectionEnabled(enabled);
    }

private:
    static inline constexpr Name s_TestArenaName{"tests/descriptor_buffer/graphics_object_arena"};
    static inline constexpr u32 s_TestWorkerThreadCount = 2u;

    Alloc::GlobalArena m_objectArena;
    GraphicsAllocator m_allocator;
    Alloc::ThreadPool m_threadPool;
    Alloc::JobSystem m_jobSystem;
    Perf::TimingRecorder m_gpuTiming;
    Graphics m_graphics;
};


////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////


// Fixture: one headless device shared across the suite. The descriptor-buffer segments are HOST-mapped and persist
// for device life, so per-case carve/free is exercised against the real global segments (resource + sampler).
class DescriptorBufferRoundTripTest : public ::testing::Test{
protected:
    static void SetUpTestSuite(){
#if defined(NWB_DEBUG) || defined(NWB_OPTIMIZE)
        // The hardening checks intentionally exercise diagnostic rejection paths.  This fixture owns a worker pool,
        // so use Google Test's re-exec death-test mode rather than forking a live multi-threaded Vulkan process.
        GTEST_FLAG_SET(death_test_style, "threadsafe");
#endif

        // The device-creation path emits log messages, and every NWB_LOGGER_* macro fatally asserts a logger is
        // installed. Register the capturing logger before bring-up so failures are recorded rather than
        // crashing the process, then keep it registered for the suite's lifetime.
        s_logger.emplace();
        s_loggerGuard.emplace(*s_logger);

        s_scope = MakeUnique<HeadlessGraphicsScope>();
        const bool initialized = s_scope->initialize();

        // No usable Vulkan device on this host -> skip the whole suite. Reported as SKIPPED, not failed.
        if(!initialized){
            GTEST_SKIP() << "Descriptor-buffer round-trip: no usable headless Vulkan device on this host; skipping suite.";
            return;
        }

        auto& device = s_scope->graphics().getDevice();
        auto& mgr = device.getDescriptorBufferManager();

        if(!mgr.isEnabled()){
            // This suite proves the required descriptor-buffer path. A host without the extension cannot exercise
            // that contract, so skip instead of treating an ordinary descriptor-set path as equivalent coverage.
            GTEST_SKIP() << "Descriptor-buffer round-trip: VK_EXT_descriptor_buffer is not enabled on this device; "
                            "skipping descriptor-buffer-only coverage.";
        }
    }

    static void TearDownTestSuite(){
        s_scope.reset();
        s_loggerGuard.reset();
        s_logger.reset();
    }

    [[nodiscard]] static GraphicsBackend::Device& device(){
        return s_scope->graphics().getDevice();
    }
    [[nodiscard]] static GraphicsBackend::DescriptorBufferManager& manager(){
        return device().getDescriptorBufferManager();
    }
    [[nodiscard]] static Alloc::GlobalArena& arena(){ return s_scope->arena(); }

protected:
    static UniquePtr<HeadlessGraphicsScope> s_scope;
    static Optional<CapturingLogger> s_logger;
    static Optional<Common::LoggerRegistrationGuard> s_loggerGuard;
};

UniquePtr<HeadlessGraphicsScope> DescriptorBufferRoundTripTest::s_scope;
Optional<CapturingLogger> DescriptorBufferRoundTripTest::s_logger;
Optional<Common::LoggerRegistrationGuard> DescriptorBufferRoundTripTest::s_loggerGuard;


[[nodiscard]] static TextureHandle CreateConcurrentTestTexture(
    GraphicsBackend::Device& device,
    const bool keepInitialState = false
){
    TextureDesc desc;
    desc
        .setWidth(4u)
        .setHeight(4u)
        .setFormat(Format::RGBA8_UNORM)
        .setInUAV(true)
        .setInitialState(ResourceStates::Common)
        .setQueueSharing(ResourceQueueSharing::GraphicsAndAsyncCompute)
    ;
    if(keepInitialState)
        desc.setKeepInitialState(true);
    return device.createTexture(desc);
}

[[nodiscard]] static TextureHandle CreateExclusiveRayOutputTestTexture(GraphicsBackend::Device& device){
    return device.createTexture(
        TextureDesc()
            .setWidth(4u)
            .setHeight(4u)
            .setFormat(Format::RGBA8_UNORM)
            .setInUAV(true)
            .setInitialState(ResourceStates::Common)
    );
}

// Graph topology IDs must be the identities emitted by the concrete Device, not local array positions. This keeps
// the native packet smoke paths honest across device recreation and distinct Compute/Transfer transports.
[[nodiscard]] static GpuPhysicalQueueId BackendQueueId(
    GraphicsBackend::Device& device,
    const CommandQueue::Enum queue
){
    return device.getPrimaryPhysicalQueue(queue);
}


// These compact graph tasks model skinning's descriptor-visible compute endpoint. They deliberately perform no
// synthetic native submission: their packet-local barriers publish the required compute states, and the task's
// accepted callback observes the same packet token as its uploads/copies.
struct SkinningGraphSelectorConsumerTask{
    struct Payload{
        GpuGraphResourceId selector;
        GpuGraphResourceId staticInput;
        bool* observedConstantBuffer = nullptr;
        bool* observedStaticInputShaderResource = nullptr;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        Buffer* const selector = context.taskGraph.bufferForResource(payload.selector);
        Buffer* const staticInput = context.taskGraph.bufferForResource(payload.staticInput);
        if(!selector || !staticInput)
            return false;

        const bool observedConstantBuffer = commandList.getBufferState(selector) == ResourceStates::ConstantBuffer;
        const bool observedStaticInputShaderResource = commandList.getBufferState(staticInput) == ResourceStates::ShaderResource;
        if(payload.observedConstantBuffer)
            *payload.observedConstantBuffer = observedConstantBuffer;
        if(payload.observedStaticInputShaderResource)
            *payload.observedStaticInputShaderResource = observedStaticInputShaderResource;
        return observedConstantBuffer && observedStaticInputShaderResource;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


struct SkinningGraphRestStreamConsumerTask{
    struct Payload{
        GpuGraphResourceId position;
        GpuGraphResourceId normal;
        GpuGraphResourceId tangent;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        Buffer* const position = context.taskGraph.bufferForResource(payload.position);
        Buffer* const normal = context.taskGraph.bufferForResource(payload.normal);
        Buffer* const tangent = context.taskGraph.bufferForResource(payload.tangent);
        if(!position || !normal || !tangent)
            return false;

        return
            commandList.getBufferState(position) == ResourceStates::ShaderResource
            && commandList.getBufferState(normal) == ResourceStates::ShaderResource
            && commandList.getBufferState(tangent) == ResourceStates::ShaderResource
        ;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


// The active-pose skinning path has three graph stages: deformation writes all skinned streams as UAVs, bounds and
// repack consume the required streams as SRVs while producing their own UAV outputs, and a finalizer publishes every
// generated stream. This probe is getter-only so packet-lowered barriers are the entire state contract.
struct SkinningGraphStateProbeTask{
    struct Expectation{
        GpuGraphResourceId resource;
        ResourceStates::Mask state = ResourceStates::Unknown;
    };

    struct Payload{
        Expectation expectations[5u] = {};
        usize expectationCount = 0u;
        bool* recorded = nullptr;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        if(payload.expectationCount == 0u || payload.expectationCount > LengthOf(payload.expectations))
            return false;

        bool ready = true;
        for(usize expectationIndex = 0u; expectationIndex < payload.expectationCount; ++expectationIndex){
            const Expectation& expectation = payload.expectations[expectationIndex];
            Buffer* const buffer = context.taskGraph.bufferForResource(expectation.resource);
            if(!buffer || commandList.getBufferState(buffer) != expectation.state){
                ready = false;
                break;
            }
        }
        if(payload.recorded)
            *payload.recorded = ready;
        return ready;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


// The ready-frontier recorder may execute one chunk on its caller and another on a worker. Hold both task thunks
// at a latch after they observe their command-list description, proving each parallel packet received a distinct
// nonzero worker-affined native lease rather than borrowing the serial/default command arena.
struct WorkerAffinedPacketTask{
    struct Payload{
        Latch* recordingStarted = nullptr;
        u32* observedWorkerIndex = nullptr;
        Buffer* expectedBuffer = nullptr;
        ResourceStates::Mask expectedBufferState = ResourceStates::Unknown;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext&
    ){
        if(
            !payload.recordingStarted
            || !payload.observedWorkerIndex
            || !payload.expectedBuffer
            || commandList.getBufferState(payload.expectedBuffer) != payload.expectedBufferState
        )
            return false;
        *payload.observedWorkerIndex = commandList.getDescription().recordingWorkerIndex;
        payload.recordingStarted->count_down();
        payload.recordingStarted->wait();
        return commandList.isRecording();
    }
};


// Minimal Vulkan 1.3 compute shader: `void main(){}`. The retirement test needs a real pipeline layout containing
// the heap's explicit set-8/9 layouts so CommandList::bindDescriptorBufferHeap records an actual heap use.
static constexpr u32 s_DescriptorHeapRetirementComputeSpirv[] = {
    0x07230203u, 0x00010600u, 0x00070000u, 0x00000005u, 0x00000000u,
    0x00020011u, 0x00000001u,
    0x0003000eu, 0x00000000u, 0x00000001u,
    0x0005000fu, 0x00000005u, 0x00000001u, 0x6e69616du, 0x00000000u,
    0x00060010u, 0x00000001u, 0x00000011u, 0x00000001u, 0x00000001u, 0x00000001u,
    0x00020013u, 0x00000002u,
    0x00030021u, 0x00000003u, 0x00000002u,
    0x00050036u, 0x00000002u, 0x00000001u, 0x00000000u, 0x00000003u,
    0x000200f8u, 0x00000004u,
    0x000100fdu,
    0x00010038u,
};


// RendererSystem requests this terminal policy only when accepted cross-queue ownership cannot be recovered. The
// Graphics owner must stop the current generation before it records another frame, leaving orderly teardown and
// recreation to the caller that owns the device lifetime.
TEST_F(DescriptorBufferRoundTripTest, DeviceRecreationRequestStopsTheCurrentGraphicsGeneration){
    HeadlessGraphicsScope recoveryScope;
    ASSERT_TRUE(recoveryScope.initialize());

    auto& graphics = recoveryScope.graphics();
    EXPECT_FALSE(graphics.isDeviceRecreationRequested());

    graphics.requestDeviceRecreation();

    EXPECT_TRUE(graphics.isDeviceRecreationRequested());
    EXPECT_FALSE(graphics.runFrame());
}


// The native registry is authoritative: graph packets and direct physical submissions must name a concrete VkQueue
// rather than infer its identity from a CommandQueue ordinal. Keep this on a real device so the registry, command
// pool selection, and submission token all agree even when a device exposes several queues of one broad class.
TEST_F(DescriptorBufferRoundTripTest, NativePhysicalQueueRegistryDrivesExactSubmission){
    auto& nativeDevice = device();
    const GpuPhysicalQueueTopology topology = nativeDevice.getPhysicalQueueTopology();
    ASSERT_NE(topology.queues, nullptr);
    ASSERT_GT(topology.queueCount, 0u);

    const GpuPhysicalQueueId graphicsQueue = nativeDevice.getPrimaryPhysicalQueue(CommandQueue::Graphics);
    ASSERT_TRUE(graphicsQueue.valid());
    ASSERT_TRUE(nativeDevice.matchesPhysicalQueueIdentity(graphicsQueue));
    EXPECT_EQ(BackendQueueId(nativeDevice, CommandQueue::Graphics), graphicsQueue);

    bool foundGraphicsQueue = false;
    for(usize index = 0u; index < topology.queueCount; ++index){
        const GpuPhysicalQueueInfo& queue = topology.queues[index];
        EXPECT_TRUE(queue.id.valid());
        EXPECT_EQ(queue.id.deviceGeneration, nativeDevice.getDeviceGeneration());
        EXPECT_EQ(nativeDevice.getPhysicalQueueInfo(queue.id), &queue);
        EXPECT_TRUE(nativeDevice.matchesPhysicalQueueIdentity(queue.id));
        EXPECT_TRUE(nativeDevice.matchesPhysicalQueueIdentity(
            queue.queueClass,
            queue.id.index,
            queue.id.deviceGeneration
        ));
        EXPECT_NE(nativeDevice.getNativeQueue(GraphicsBackend::ObjectTypes::VK_Queue, queue.id), Object(nullptr));
        foundGraphicsQueue = foundGraphicsQueue || queue.id == graphicsQueue;
    }
    EXPECT_TRUE(foundGraphicsQueue);

    CommandListParameters parameters;
    parameters.setPhysicalQueue(graphicsQueue);
    auto commandList = nativeDevice.createCommandList(parameters);
    ASSERT_NE(commandList.get(), nullptr);
    EXPECT_EQ(commandList->getDescription().physicalQueue, graphicsQueue);
    commandList->open();
    commandList->close();

    CommandList* const commandLists[] = { commandList.get() };
    const QueueSubmissionToken token = nativeDevice.executeCommandLists(
        commandLists,
        LengthOf(commandLists),
        graphicsQueue,
        QueueSubmissionDesc{}
    );
    ASSERT_TRUE(token.valid());
    EXPECT_TRUE(token.matchesPhysicalQueue(graphicsQueue.index, graphicsQueue.deviceGeneration));
    EXPECT_EQ(token.queue, CommandQueue::Graphics);

#if !defined(NWB_FINAL) || defined(NWB_ENABLE_TEST_FEATURE_OVERRIDES)
    // The recovery proof reads the same Device-boundary capture below. Exercise it on the always-available
    // Graphics transport too, so the test seam itself remains live on hosts without a dedicated Transfer family.
    auto waitConsumer = nativeDevice.createCommandList(parameters);
    ASSERT_NE(waitConsumer.get(), nullptr);
    waitConsumer->open();
    waitConsumer->close();
    const QueueSubmissionToken waitTokens[] = { token };
    CommandList* const waitConsumerLists[] = { waitConsumer.get() };
    nativeDevice.clearSubmissionWaitTokensForTesting();
    nativeDevice.armSubmissionWaitCaptureForTesting();
    const QueueSubmissionToken waitConsumerToken = nativeDevice.executeCommandLists(
        waitConsumerLists,
        LengthOf(waitConsumerLists),
        graphicsQueue,
        QueueSubmissionDesc().setWaitTokens(waitTokens, LengthOf(waitTokens))
    );
    ASSERT_TRUE(waitConsumerToken.valid());
    ASSERT_EQ(nativeDevice.lastSubmissionWaitTokenCountForTesting(graphicsQueue), 1u);
    const QueueSubmissionToken capturedWait = nativeDevice.lastSubmissionWaitTokenForTesting(graphicsQueue, 0u);
    EXPECT_EQ(capturedWait.queue, token.queue);
    EXPECT_EQ(capturedWait.value, token.value);
    EXPECT_EQ(capturedWait.physicalQueueIndex, token.physicalQueueIndex);
    EXPECT_EQ(capturedWait.deviceGeneration, token.deviceGeneration);
#endif

    EXPECT_TRUE(nativeDevice.waitForIdle());
}


// A physical-queue ID is more precise than its broad CommandQueue class. When a Graphics family exposes a second
// queue, explicitly opted-in graph work may cross between them; Vulkan requires a timeline wait but no queue-family
// ownership transfer. Exercise the complete compiler -> recorder -> submitter path on a real Device.
TEST_F(DescriptorBufferRoundTripTest, SameClassGraphicsQueuesRouteGraphPacketsAndStateHandoffs){
    HeadlessGraphicsScope multiQueueScope;
    ASSERT_TRUE(multiQueueScope.setSameClassMultiQueueEnabled(true));
    if(!multiQueueScope.initialize())
        GTEST_SKIP() << "Same-class queue routing: no usable headless Vulkan device on this host.";

    auto& device = multiQueueScope.graphics().getDevice();
    if(!device.getDescriptorBufferManager().isEnabled())
        GTEST_SKIP() << "Same-class queue routing: VK_EXT_descriptor_buffer is unavailable on this device.";

    const GpuPhysicalQueueTopology topology = device.getPhysicalQueueTopology();
    const GpuPhysicalQueueId primaryGraphicsQueue = device.getPrimaryPhysicalQueue(CommandQueue::Graphics);
    const GpuPhysicalQueueInfo* secondaryGraphicsQueue = nullptr;
    for(usize queueIndex = 0u; queueIndex < topology.queueCount; ++queueIndex){
        const GpuPhysicalQueueInfo& candidate = topology.queues[queueIndex];
        if(
            candidate.queueClass == CommandQueue::Graphics
            && candidate.id != primaryGraphicsQueue
            && candidate.familyIndex == device.getQueueFamilyIndex(primaryGraphicsQueue)
        ){
            secondaryGraphicsQueue = &candidate;
            break;
        }
    }
    if(!secondaryGraphicsQueue){
        GTEST_SKIP() << "Same-class queue routing: adapter exposes only one Graphics queue.";
    }

    static constexpr u32 s_SourceWords[] = {
        0x1e35a7c9u,
        0x73b4d2f0u,
        0x0badbeefu,
        0x9e3779b9u,
    };
    auto source = device.createBuffer(
        BufferDesc()
            .setByteSize(sizeof(s_SourceWords))
            .setInitialState(ResourceStates::Common)
            .setQueueSharing(ResourceQueueSharing::Exclusive)
    );
    auto destination = device.createBuffer(
        BufferDesc()
            .setByteSize(sizeof(s_SourceWords))
            .setInitialState(ResourceStates::Common)
            .setQueueSharing(ResourceQueueSharing::Exclusive)
            .setCpuAccess(CpuAccessMode::Read)
    );
    ASSERT_NE(source.get(), nullptr);
    ASSERT_NE(destination.get(), nullptr);

    GpuTaskGraph graph(multiQueueScope.arena());
    const GpuGraphResourceId sourceResource = graph.importBuffer(
        source,
        GpuGraphResourceDesc{}
            .setIdentity(Name("tests/descriptor_buffer/same_class_source"))
            .setMarkerLabel("Same Class Source")
            .setType(GpuGraphResourceType::Buffer)
            .setInitialState(ResourceStates::Common)
    );
    const GpuGraphResourceId destinationResource = graph.importBuffer(
        destination,
        GpuGraphResourceDesc{}
            .setIdentity(Name("tests/descriptor_buffer/same_class_destination"))
            .setMarkerLabel("Same Class Destination")
            .setType(GpuGraphResourceType::Buffer)
            .setInitialState(ResourceStates::Common)
    );
    const GpuUploadBlobId sourceBlob = graph.copyUploadData(s_SourceWords, sizeof(s_SourceWords), alignof(u32));
    ASSERT_TRUE(sourceResource.valid());
    ASSERT_TRUE(destinationResource.valid());
    ASSERT_TRUE(sourceBlob.valid());

    GpuQueueRequest graphicsTransferRequest;
    graphicsTransferRequest.requiredCapabilities = GpuQueueCapability::Transfer;
    graphicsTransferRequest.preferredQueue = GpuQueuePreference::Graphics;
    graphicsTransferRequest.allowFallback = false;
    graphicsTransferRequest.compilerMayOverridePreference = false;

    GpuTaskSchedulingHint uploadScheduling;
    uploadScheduling.cost = GpuTaskCostHint::Large;
    uploadScheduling.forceSubmissionBoundary = true;
    uploadScheduling.allowPacketMerge = false;
    uploadScheduling.allowSameClassQueueRouting = true;
    GpuTaskDesc uploadDesc;
    uploadDesc
        .setIdentity(Name("tests/descriptor_buffer/same_class_upload"))
        .setMarkerLabel("Same Class Upload")
        .setQueue(graphicsTransferRequest)
        .setScheduling(uploadScheduling)
    ;
    QueueSubmissionToken uploadToken;
    const GpuTaskId uploadTask = graph.addUploadBufferTask(
        uploadDesc,
        GpuUploadBufferTaskDesc{
            .source = sourceBlob,
            .destination = sourceResource,
            .finalState = ResourceStates::CopySource,
            .acceptedToken = &uploadToken,
        }
    );
    ASSERT_TRUE(uploadTask.valid());

    GpuTaskSchedulingHint copyScheduling;
    copyScheduling.cost = GpuTaskCostHint::Medium;
    copyScheduling.forceSubmissionBoundary = true;
    copyScheduling.allowPacketMerge = false;
    copyScheduling.allowSameClassQueueRouting = true;
    const GpuCopyBufferTaskRegion copyRegion{
        .source = sourceResource,
        .sourceOffsetBytes = 0u,
        .destination = destinationResource,
        .destinationOffsetBytes = 0u,
        .dataSizeBytes = sizeof(s_SourceWords),
    };
    GpuTaskDesc copyDesc;
    copyDesc
        .setIdentity(Name("tests/descriptor_buffer/same_class_copy"))
        .setMarkerLabel("Same Class Copy")
        .setQueue(graphicsTransferRequest)
        .setScheduling(copyScheduling)
    ;
    QueueSubmissionToken copyToken;
    const GpuTaskId copyTask = graph.addCopyBufferTask(
        copyDesc,
        GpuCopyBufferTaskDesc{
            .regions = &copyRegion,
            .regionCount = 1u,
            .acceptedToken = &copyToken,
        }
    );
    ASSERT_TRUE(copyTask.valid());

    GpuTaskGraphAnalysis analysis(multiQueueScope.arena());
    GpuTaskGraphQueueAssignments assignments(multiQueueScope.arena());
    GpuCompiledGraph compiledGraph(multiQueueScope.arena());
    Alloc::ScratchArena scratchArena(Name("tests/descriptor_buffer/same_class_queue_routing_scratch"));
    const GpuTaskGraphCompiler compiler;
    ASSERT_TRUE(compiler.compile(graph, analysis, topology, assignments, compiledGraph, scratchArena));

    const GpuTaskQueueAssignment* const uploadAssignment = assignments.find(uploadTask);
    const GpuTaskQueueAssignment* const copyAssignment = assignments.find(copyTask);
    ASSERT_NE(uploadAssignment, nullptr);
    ASSERT_NE(copyAssignment, nullptr);
    EXPECT_EQ(uploadAssignment->queue, primaryGraphicsQueue);
    EXPECT_EQ(copyAssignment->queue, secondaryGraphicsQueue->id);
    EXPECT_EQ(copyAssignment->reason, GpuTaskQueueAssignmentReason::SameClassRouting);
    const GpuSubmissionPacketId uploadPacket = compiledGraph.packetForTask(uploadTask);
    const GpuSubmissionPacketId copyPacket = compiledGraph.packetForTask(copyTask);
    ASSERT_TRUE(uploadPacket.valid());
    ASSERT_TRUE(copyPacket.valid());
    ASSERT_EQ(compiledGraph.packet(copyPacket).dependencyCount, 1u);
    EXPECT_EQ(compiledGraph.packetDependencies(copyPacket)[0u].producer, uploadPacket);

    GpuRecordedGraph recordedGraph(multiQueueScope.arena());
    const GpuNativePacketRecorder recorder(device);
    ASSERT_TRUE(recorder.recordPacketRangeInCompileOrder(
        graph,
        compiledGraph,
        compiledGraph.allPacketRange(),
        nullptr,
        0u,
        recordedGraph
    ));
    ASSERT_NE(recordedGraph.packetFinalStateSeed(uploadPacket), nullptr);
    ASSERT_NE(recordedGraph.packetFinalStateSeed(copyPacket), nullptr);

    GpuGraphSubmissionTransaction transaction(multiQueueScope.arena());
    transaction.reset(compiledGraph);
    const GpuTaskGraphSubmitter submitter(device);
    ASSERT_TRUE(submitter.submitPacketRangeInCompileOrder(
        graph,
        compiledGraph,
        recordedGraph,
        compiledGraph.allPacketRange(),
        nullptr,
        0u,
        nullptr,
        0u,
        transaction,
        scratchArena
    ));
    ASSERT_TRUE(uploadToken.matchesPhysicalQueue(primaryGraphicsQueue.index, primaryGraphicsQueue.deviceGeneration));
    ASSERT_TRUE(copyToken.matchesPhysicalQueue(
        secondaryGraphicsQueue->id.index,
        secondaryGraphicsQueue->id.deviceGeneration
    ));
    ASSERT_TRUE(device.waitForIdle());

    const u32* const copiedWords = static_cast<const u32*>(device.mapBuffer(destination.get(), CpuAccessMode::Read));
    ASSERT_NE(copiedWords, nullptr);
    for(usize wordIndex = 0u; wordIndex < LengthOf(s_SourceWords); ++wordIndex)
        EXPECT_EQ(copiedWords[wordIndex], s_SourceWords[wordIndex]);
    device.unmapBuffer(destination.get());
}


// A timeline value is only meaningful for the Device that issued it.  Make the rejection observable at the native
// submission boundary so an imported graph completion cannot accidentally wait on a recycled queue timeline after
// device recreation.
TEST_F(DescriptorBufferRoundTripTest, QueueSubmissionRejectsRetiredDeviceGeneration){
    QueueSubmissionToken retiredToken;
    {
        HeadlessGraphicsScope producerScope;
        ASSERT_TRUE(producerScope.initialize());
        auto& producer = producerScope.graphics().getDevice();

        auto producerCommandList = producer.createCommandList();
        ASSERT_NE(producerCommandList.get(), nullptr);
        producerCommandList->open();
        producerCommandList->close();
        CommandList* const producerCommandLists[] = { producerCommandList.get() };

        retiredToken = producer.executeCommandLists(
            producerCommandLists,
            LengthOf(producerCommandLists),
            CommandQueue::Graphics,
            QueueSubmissionDesc{}
        );
        ASSERT_TRUE(retiredToken.valid());
        ASSERT_TRUE(retiredToken.hasPhysicalQueueIdentity());
        EXPECT_TRUE(producer.matchesPhysicalQueueIdentity(
            retiredToken.queue,
            retiredToken.physicalQueueIndex,
            retiredToken.deviceGeneration
        ));
    }

    HeadlessGraphicsScope consumerScope;
    ASSERT_TRUE(consumerScope.initialize());
    auto& consumer = consumerScope.graphics().getDevice();
    EXPECT_NE(retiredToken.deviceGeneration, consumer.getDeviceGeneration());
    EXPECT_FALSE(consumer.matchesPhysicalQueueIdentity(
        retiredToken.queue,
        retiredToken.physicalQueueIndex,
        retiredToken.deviceGeneration
    ));

    const QueueSubmissionDesc staleWait = QueueSubmissionDesc().setWaitTokens(&retiredToken, 1u);
#if defined(NWB_DEBUG) || defined(NWB_OPTIMIZE)
    EXPECT_DEATH_IF_SUPPORTED({
        EXPECT_FALSE(consumer.executeCommandLists(nullptr, 0u, CommandQueue::Graphics, staleWait).valid());
    }, "");
#else
    EXPECT_FALSE(consumer.executeCommandLists(nullptr, 0u, CommandQueue::Graphics, staleWait).valid());
#endif
}


////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////


// An external pixel capture must be able to hold the last completed image without accidentally opening another frame.
// The suspension still observes terminal device state so it cannot conceal a recovery/recreation request.
TEST_F(DescriptorBufferRoundTripTest, FrameSubmissionSuspensionFreezesTheFrameClockWithoutMaskingDeviceRecreation){
    HeadlessGraphicsScope captureScope;
    ASSERT_TRUE(captureScope.initialize());

    auto& graphics = captureScope.graphics();
    const u64 frameIndex = graphics.getFrameIndex();
    graphics.setFrameSubmissionSuspended(true);

    EXPECT_TRUE(graphics.isFrameSubmissionSuspended());
    EXPECT_TRUE(graphics.runFrame());
    EXPECT_EQ(frameIndex, graphics.getFrameIndex());

    graphics.requestDeviceRecreation();
    EXPECT_FALSE(graphics.runFrame());
}


struct NativePacketPrefixTask{
    struct Payload{
        Buffer* buffer = nullptr;
        ResourceStates::Mask expectedState = ResourceStates::Unknown;
        Buffer* additionalBuffer = nullptr;
        ResourceStates::Mask expectedAdditionalBufferState = ResourceStates::Unknown;
        Texture* texture = nullptr;
        ResourceStates::Mask expectedTextureState = ResourceStates::Unknown;
        Texture* additionalTexture = nullptr;
        ResourceStates::Mask expectedAdditionalTextureState = ResourceStates::Unknown;
        Texture* thirdTexture = nullptr;
        ResourceStates::Mask expectedThirdTextureState = ResourceStates::Unknown;
        bool* recorded = nullptr;
        QueueSubmissionToken* acceptedToken = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        static_cast<void>(context);
        if(!payload.buffer)
            return false;
        bool ready = commandList.getBufferState(payload.buffer) == payload.expectedState;
        if(payload.additionalBuffer)
            ready = ready && commandList.getBufferState(payload.additionalBuffer) == payload.expectedAdditionalBufferState;
        if(payload.texture)
            ready = ready && commandList.getTextureSubresourceState(payload.texture, 0u, 0u) == payload.expectedTextureState;
        if(payload.additionalTexture)
            ready = ready && commandList.getTextureSubresourceState(payload.additionalTexture, 0u, 0u) == payload.expectedAdditionalTextureState;
        if(payload.thirdTexture)
            ready = ready && commandList.getTextureSubresourceState(payload.thirdTexture, 0u, 0u) == payload.expectedThirdTextureState;
        if(payload.recorded)
            *payload.recorded = ready;
        return ready;
    }

    static void accepted(Payload& payload, const QueueSubmissionToken& token){
        if(payload.acceptedToken)
            *payload.acceptedToken = token;
    }
};


// The opaque CSG receiver-span task consumes receiver-surface event StorageImage aliases and publishes span
// aliases for interval combine. This getter-only probe observes the graph-lowered entry states before the native
// span dispatcher can perform any compatibility transition.
struct NativePacketCsgReceiverSpanProbeTask{
    struct Payload{
        Texture* receiverEventData = nullptr;
        Texture* receiverEventCount = nullptr;
        Texture* receiverSpanData = nullptr;
        Texture* receiverSpanCount = nullptr;
        bool* recorded = nullptr;
    };

    [[nodiscard]] static bool record(
        const Payload& payload,
        CommandList& commandList,
        const GpuTaskRecordContext& context
    ){
        static_cast<void>(context);
        if(
            !payload.receiverEventData
            || !payload.receiverEventCount
            || !payload.receiverSpanData
            || !payload.receiverSpanCount
        )
            return false;
        const auto hasUavRange = [&commandList](Texture* texture, const u32 finalArraySlice){
            return commandList.getTextureSubresourceState(texture, 0u, 0u) == ResourceStates::UnorderedAccess
                && commandList.getTextureSubresourceState(texture, finalArraySlice, 0u) == ResourceStates::UnorderedAccess
            ;
        };
        const bool ready =
            hasUavRange(payload.receiverEventData, 31u)
            && hasUavRange(payload.receiverEventCount, 0u)
            && hasUavRange(payload.receiverSpanData, 15u)
            && hasUavRange(payload.receiverSpanCount, 0u)
        ;
        if(payload.recorded)
            *payload.recorded = ready;
        return ready;
    }
};


// A CSG interval-combine task consumes five producer StorageImage aliases and publishes four more. This probe
